// Adatta ARRAY_FIELD, FILTER_FIELD e TIMESTAMP_FIELD alla forma della tua risposta JSON.
// L'idea: tieni in memoria (static data, sopravvive ai riavvii n8n) l'ultimo timestamp visto,
// e manda solo le voci nuove che superano il filtro che ti interessa.
const ARRAY_FIELD = 'items';       // nome del campo che contiene l'array nella risposta
const FILTER_VALUES = [];          // es. ['errore','warning'] — lascia [] per non filtrare
const FILTER_FIELD = 'tipo';       // campo su cui applicare FILTER_VALUES
const TIMESTAMP_FIELD = 'ts';      // campo timestamp/ordinabile, per non ripetere le stesse voci

const state = $getWorkflowStaticData('global');
const lastTs = state.lastTs || '';
const raw = ($input.first().json[ARRAY_FIELD] || []);
const events = raw
  .filter(e => !FILTER_VALUES.length || FILTER_VALUES.includes(e[FILTER_FIELD]))
  .filter(e => String(e[TIMESTAMP_FIELD] || '') > lastTs)
  .reverse();
if (events.length) state.lastTs = String(events[events.length - 1][TIMESTAMP_FIELD] || lastTs);
return events.map(e => ({ json: {
  text: `🔔 ${e[FILTER_FIELD] || 'evento'}\n${JSON.stringify(e).slice(0, 300)}`
} }));
